36	/**
37	 * Status bar widget that shows the CODEOWNERS owners of the currently
38	 * selected file.
39	 *
40	 * <p>Re-resolution is driven by three event sources:
41	 * <ul>
42	 *   <li>{@link FileEditorManagerListener} — the selected file changed.</li>
43	 *   <li>{@link BulkFileListener} on VFS — the CODEOWNERS file (or the active
44	 *       file's path) changed on disk.</li>
45	 *   <li>{@link PsiTreeChangeAdapter} on {@link PsiManager} — an in-editor
46	 *       edit to a CODEOWNERS file (the VFS stamp does not change until save).</li>
47	 * </ul>
48	 *
49	 * <p>The work itself (computing the matching rule) is offloaded to a
50	 * non-blocking read action, so the UI thread never parses or matches.
51	 *
52	 * <p>Clicking the widget opens the CODEOWNERS file at the matching rule's
53	 * line; if no rule matches but a CODEOWNERS file exists, it opens the file
54	 * at the top.
55	 */
56	public final class CodeownersStatusBarWidget implements StatusBarWidget, StatusBarWidget.IconPresentation {
57	
58	  private final Project project;
59	  private StatusBar statusBar;
60	
61	  /**
62	   * Most recent resolution result. Written on UI thread, read by presentation getters.
63	   */
64	  private volatile CodeownersOwnerResolution resolution = CodeownersOwnerResolution.NONE;
65	
66	  public CodeownersStatusBarWidget(@NotNull Project project) {
67	    this.project = project;
68	  }
69	
70	  private static boolean isCodeowners(@Nullable PsiFile file) {
71	    return file != null && "CODEOWNERS".equals(file.getName());
72	  }
73	
74	  /**
75	   * A file "needs suggestions" when it has no specific owner: no rule matched,
76	   * the matched rule lists no owners, or it is owned only by the global wildcard
77	   * rule ({@code *} / {@code **}), which assigns a repo-wide default rather than
78	   * a real owner for this particular file.
79	   */
80	  static boolean needsSuggestions(@Nullable CodeownersRule rule) {
81	    if (rule == null || rule.owners().isEmpty()) return true;
82	    return isGlobalWildcard(rule.pattern());
83	  }
84	
85	  private static boolean isGlobalWildcard(@NotNull String pattern) {
86	    String p = pattern.trim();
87	    return p.equals("*") || p.equals("**");
88	  }
89	
90	  @Override
91	  public @NotNull String ID() {
92	    return CodeownersStatusBarWidgetFactory.ID;
93	  }
94	
95	  @Override
96	  public @NotNull WidgetPresentation getPresentation() {
97	    return this;
98	  }
99	
100	  @Override
101	  public void install(@NotNull StatusBar statusBar) {
102	    this.statusBar = statusBar;
103	
104	    MessageBusConnection bus = project.getMessageBus().connect(this);
105	    bus.subscribe(FileEditorManagerListener.FILE_EDITOR_MANAGER, new FileEditorManagerListener() {
106	      @Override
107	      public void selectionChanged(@NotNull FileEditorManagerEvent event) {
108	        scheduleUpdate();
109	      }
110	
111	      @Override
112	      public void fileOpened(@NotNull FileEditorManager source, @NotNull VirtualFile file) {
113	        scheduleUpdate();
114	      }
115	    });
116	    bus.subscribe(VirtualFileManager.VFS_CHANGES, new BulkFileListener() {
117	      @Override
118	      public void after(@NotNull List<? extends VFileEvent> events) {
119	        for (VFileEvent e : events) {
120	          String path = e.getPath();
121	          // Any rename, content change, create, or delete touching a file
122	          // named CODEOWNERS, or touching the currently-active file, warrants
123	          // a re-resolve.
124	          if (path.endsWith("/CODEOWNERS") || path.equals("CODEOWNERS")) {
125	            scheduleUpdate();
126	            return;
127	          }
128	        }
129	      }
130	    });
131	
132	    // PSI changes catch unsaved edits to CODEOWNERS — VFS does not fire for those.
133	    PsiManager.getInstance(project).addPsiTreeChangeListener(new PsiTreeChangeAdapter() {
134	      @Override
135	      public void childrenChanged(@NotNull PsiTreeChangeEvent event) {
136	        if (isCodeowners(event.getFile())) scheduleUpdate();
137	      }
138	
139	      @Override
140	      public void propertyChanged(@NotNull PsiTreeChangeEvent event) {
141	        if (isCodeowners(event.getFile())) scheduleUpdate();
142	      }
143	    }, this);
144	
145	    scheduleUpdate();
146	  }
147	
148	  /**
149	   * Recompute the owners off the UI thread, then push the result back via
150	   * {@link StatusBar#updateWidget}. Cancellable via {@link Disposable#dispose()}.
151	   */
152	  private void scheduleUpdate() {
153	    if (project.isDisposed()) return;
154	    ReadAction.nonBlocking(() -> {
155	              VirtualFile current = currentFile();
156	              return CodeownersService.getInstance(project).resolveOwners(current);
157	            })
158	            .expireWith(this)
159	            .finishOnUiThread(ModalityState.any(), result -> {
160	              resolution = result;
161	              if (statusBar != null) statusBar.updateWidget(ID());
162	            })
163	            .submit(AppExecutorUtil.getAppExecutorService());
164	  }
165	
166	  // ---- IconPresentation ----
167	
168	  private @Nullable VirtualFile currentFile() {
169	    if (project.isDisposed()) return null;
170	    VirtualFile[] selected = FileEditorManager.getInstance(project).getSelectedFiles();
171	    return selected.length > 0 ? selected[0] : null;
172	  }
173	
174	  @Override
175	  public void dispose() {
176	    // MessageBusConnection and PSI listener are tied to `this` and disposed by the platform.
177	    statusBar = null;
178	  }
179	
180	  @Override
181	  public @NotNull Icon getIcon() {
182	    CodeownersRule rule = resolution.rule();
183	    // No specific owner (no match, no owners, or only the global wildcard):
184	    // surface the "access" glyph, matching the click → suggestion behaviour.
185	    if (needsSuggestions(rule)) return AllIcons.CodeWithMe.CwmAccess;
186	    return rule.owners().size() == 1 ? AllIcons.General.User : AllIcons.CodeWithMe.Users;
187	  }
188	
189	  @Override
190	  public @NotNull String getTooltipText() {
191	    CodeownersOwnerResolution res = resolution;
192	    if (res.isEmpty()) return "No CODEOWNERS rule matches this file";
193	    CodeownersRule rule = res.rule();
194	    if (rule == null) return "No CODEOWNERS rule matches this file";
195	    String codeowners = !rule.owners().isEmpty() ?
196	            StringUtil.escapeXmlEntities(String.join(", ", rule.owners())) : "Unknown";
197	    // Only present for rules inside a GitLab section that declares one, e.g. [Backend][2].
198	    String approvals = rule.approvalCount() != null
199	            ? "<b>Approvals required:</b> " + rule.approvalCount() + "<br>"
200	            : "";
201	    return "<html>" +
202	            "<b>Owners:</b> " + codeowners + "<br>" +
203	            "<b>Pattern:</b> <em>" + StringUtil.escapeXmlEntities(rule.pattern()) + "</em><br>" +
204	            approvals +
205	            "<b>Source:</b> " + StringUtil.escapeXmlEntities(displaySourcePath(rule)) +
206	            "</html>";
207	  }
208	
209	  @Override
210	  public @NotNull Consumer<MouseEvent> getClickConsumer() {
211	    return this::onClick;
212	  }
213	
214	  /**
215	   * When the selected file has no specific owner, offers owner suggestions;
216	   * otherwise navigates to the matching rule. That is the moment the user most
217	   * needs help, so the click is repurposed to a suggestion popup there.
218	   */
219	  private void onClick(@NotNull MouseEvent e) {
220	    if (project.isDisposed()) return;
221	    if (needsSuggestions(resolution.rule())) {
222	      VirtualFile target = currentFile();
223	      if (target != null) {
224	        CodeownersSuggestionPopup.show(project, target, new RelativePoint(e));
225	        return;
226	      }
227	    }
228	    navigateToMatchedRule();
229	  }
230	
231	  /**
232	   * Opens the active CODEOWNERS file at the matched rule's line. If no rule
233	   * matches but a CODEOWNERS file is known, opens it at line 1 so the user
234	   * can verify the file content. Does nothing when no CODEOWNERS file exists.
235	   */
236	  private void navigateToMatchedRule() {
237	    if (project.isDisposed()) return;
238	    CodeownersOwnerResolution res = resolution;
239	    CodeownersRule rule = res.rule();
240	    VirtualFile target;
241	    int line;
242	    if (rule != null && rule.sourceFile() != null && rule.sourceFile().isValid()) {
243	      target = rule.sourceFile();
244	      line = rule.lineNumber();
245	    } else {
246	      target = CodeownersService.getInstance(project).getCodeownersFile();
247	      if (target == null || !target.isValid()) return;
248	      line = 0;
249	    }
250	    new OpenFileDescriptor(project, target, line, 0).navigate(true);
251	  }
252	
253	  private @NotNull String displaySourcePath(@NotNull CodeownersRule rule) {
254	    VirtualFile vf = rule.sourceFile();
255	    if (vf == null) return "(unknown)";
256	    String path = vf.getPath();
257	    String base = project.getBasePath();
258	    if (base != null && path.startsWith(base + "/")) {
259	      return path.substring(base.length() + 1);
260	    }
261	    return path;
262	  }
263	}
