27	/**
28	 * Computes and shows owner suggestions for a file that has no CODEOWNERS owner.
29	 *
30	 * <p>Triggered by clicking the status-bar widget. Resolving the CODEOWNERS
31	 * context, gathering completion candidates, and especially the per-file
32	 * {@code git log} all happen on a background task; the chooser popup is then
33	 * shown on the EDT. Picking a suggestion appends a rule
34	 * ({@code /relative/path @owner}) to the CODEOWNERS file and opens it there.
35	 *
36	 * <p>If no CODEOWNERS file governs the target, nothing is shown — there would be
37	 * nowhere to add the rule.
38	 */
39	public final class CodeownersSuggestionPopup {
40	
41	  private CodeownersSuggestionPopup() {
42	  }
43	
44	  public static void show(@NotNull Project project, @NotNull VirtualFile target, @NotNull RelativePoint where) {
45	    new Task.Backgroundable(project, "Computing CODEOWNERS Suggestions", true) {
46	      private List<OwnerSuggestion> suggestions = List.of();
47	      private CodeownersService.FileContext context;
48	
49	      @Override
50	      public void run(@NotNull ProgressIndicator indicator) {
51	        CodeownersService.FileContext ctx =
52	                ReadAction.compute(() -> CodeownersService.getInstance(project).fileContext(target));
53	        if (ctx == null) return;
54	        context = ctx;
55	
56	        List<OwnerCandidate> candidates = ReadAction.compute(() -> {
57	          PsiFile psi = PsiManager.getInstance(project).findFile(ctx.codeownersFile());
58	          return psi == null ? List.<OwnerCandidate>of() : new CodeownersOwnerCollector().collect(psi);
59	        });
60	
61	        Map<String, Integer> authors =
62	                CodeownersGitContributorService.getInstance(project).getFileAuthorCommits(target);
63	
64	        suggestions = CodeownersOwnerSuggester.suggest(
65	                ctx.relativePath(), ctx.rules(), candidates, authors);
