19	/**
20	 * Project-level cache of unique Git author emails, used by
21	 * {@link CodeownersGitOwnerSource} to seed completion with people who have
22	 * actually touched the codebase.
23	 *
24	 * <p>The service never blocks the caller: {@link #getCachedContributors()}
25	 * returns whatever is currently cached and asynchronously triggers a refresh
26	 * if the TTL has elapsed. The refresh uses {@code git log --format=%ae} via
27	 * {@link GeneralCommandLine}, bounded to {@value #MAX_COMMITS} commits and
28	 * {@value #TIMEOUT_MS} ms so it stays cheap even on large repositories. If
29	 * the {@code git} binary is missing, the working directory isn't a repo, or
30	 * the command times out, the result is an empty list — the rest of the
31	 * completion experience still works.
32	 *
33	 * <p>The {@code git log} call deliberately runs on a pooled background
34	 * thread; the service avoids ever reaching VFS or PSI to keep refresh
35	 * thread-safety simple.
36	 */
37	@Service(Service.Level.PROJECT)
38	public final class CodeownersGitContributorService {
39	
40	  /**
41	   * How long a cached result stays fresh before another refresh is scheduled.
42	   */
43	  static final long TTL_MS = 5L * 60 * 1000;
44	  /**
45	   * Hard cap on commits walked by {@code git log}, to bound runtime on big repos.
46	   */
47	  static final int MAX_COMMITS = 5000;
48	  /**
49	   * Hard cap on the time spent waiting for {@code git} to respond.
50	   */
51	  static final int TIMEOUT_MS = 5000;
52	
53	  private final Project project;
54	  private final Object refreshLock = new Object();
55	  private volatile List<String> cached = List.of();
56	  private volatile long lastRefreshMs = 0L;
57	  private boolean refreshing = false;
58	
59	  public CodeownersGitContributorService(@NotNull Project project) {
60	    this.project = project;
61	  }
62	
63	  public static @NotNull CodeownersGitContributorService getInstance(@NotNull Project project) {
64	    return project.getService(CodeownersGitContributorService.class);
65	  }
66	
67	  private static @Nullable File toLocalDir(@Nullable VirtualFile vf) {
68	    if (vf == null || !vf.isValid() || !vf.isInLocalFileSystem()) return null;
69	    File f = new File(vf.getPath());
70	    return f.isDirectory() ? f : null;
71	  }
72	
73	  /**
74	   * Drives {@code git log -<n> --format=%ae --no-merges}. Package-private so
75	   * tests can exercise it directly against a temporary git repo if they want;
76	   * the rest of the service treats failures uniformly as "no contributors".
77	   */
78	  static @NotNull List<String> queryGitAuthors(@NotNull File workDir) {
79	    GeneralCommandLine cmd = new GeneralCommandLine(
80	            "git", "log", "-" + MAX_COMMITS, "--format=%ae", "--no-merges");
81	    cmd.setWorkDirectory(workDir);
82	    cmd.setCharset(java.nio.charset.StandardCharsets.UTF_8);
83	    try {
84	      ProcessOutput output = ExecUtil.execAndGetOutput(cmd, TIMEOUT_MS);
85	      if (output.getExitCode() != 0 || output.isTimeout()) return List.of();
86	      Set<String> seen = new LinkedHashSet<>();
87	      for (String line : output.getStdoutLines()) {
88	        String trimmed = line.trim();
89	        // Filter to plausibly-email-shaped values to avoid surfacing the
90	        // empty placeholders Git emits for malformed commits.
91	        if (trimmed.isEmpty() || trimmed.indexOf('@') <= 0) continue;
92	        seen.add(trimmed);
93	      }
94	      return seen.stream().sorted().toList();
95	    } catch (ExecutionException ignored) {
96	      return List.of();
97	    }
98	  }
99	
100	  /**
101	   * Drives {@code git log -<n> --format=%ae --no-merges -- <file>} and tallies
102	   * the authors. Package-private so tests can run it against a temporary repo.
103	   */
104	  static @NotNull Map<String, Integer> queryFileAuthorCommits(@NotNull File workDir, @NotNull String filePath) {
105	    GeneralCommandLine cmd = new GeneralCommandLine(
106	            "git", "log", "-" + MAX_COMMITS, "--format=%ae", "--no-merges", "--", filePath);
107	    cmd.setWorkDirectory(workDir);
108	    cmd.setCharset(java.nio.charset.StandardCharsets.UTF_8);
109	    try {
110	      ProcessOutput output = ExecUtil.execAndGetOutput(cmd, TIMEOUT_MS);
111	      if (output.getExitCode() != 0 || output.isTimeout()) return Map.of();
112	      Map<String, Integer> counts = new LinkedHashMap<>();
113	      for (String line : output.getStdoutLines()) {
114	        String trimmed = line.trim();
115	        if (trimmed.isEmpty() || trimmed.indexOf('@') <= 0) continue;
116	        counts.merge(trimmed, 1, Integer::sum);
117	      }
118	      return counts;
119	    } catch (ExecutionException ignored) {
120	      return Map.of();
121	    }
122	  }
123	
124	  /**
125	   * Counts, per author e-mail, the commits that touched {@code file}. Used to
126	   * weight owner suggestions toward the people who actually wrote the file.
127	   *
128	   * <p>Unlike {@link #getCachedContributors()} this is computed on demand (it is
129	   * called from a user-initiated background task, not during typing) and is not
130	   * cached. Returns an empty map if {@code git} is unavailable, the file isn't
131	   * tracked, or the command fails. Runs a {@code git} subprocess — never call it
132	   * on the EDT.
133	   */
134	  public @NotNull Map<String, Integer> getFileAuthorCommits(@NotNull VirtualFile file) {
135	    if (project.isDisposed() || !file.isInLocalFileSystem()) return Map.of();
136	    File workDir = resolveWorkDir();
137	    return workDir == null ? Map.of() : queryFileAuthorCommits(workDir, file.getPath());
138	  }
139	
140	  /**
141	   * @return the most recently cached list of contributor emails. Triggers a
142	   * background refresh as a side effect if the TTL has elapsed; never blocks.
143	   */
144	  public @NotNull List<String> getCachedContributors() {
145	    long now = System.currentTimeMillis();
146	    if (now - lastRefreshMs > TTL_MS) {
147	      scheduleRefresh();
148	    }
149	    return cached;
150	  }
151	
152	  private void scheduleRefresh() {
153	    synchronized (refreshLock) {
154	      if (refreshing) return;
155	      refreshing = true;
156	    }
157	    ApplicationManager.getApplication().executeOnPooledThread(this::refreshNow);
158	  }
159	
160	  private void refreshNow() {
161	    try {
162	      if (project.isDisposed()) return;
163	      File workDir = resolveWorkDir();
164	      cached = workDir == null ? List.of() : queryGitAuthors(workDir);
165	      lastRefreshMs = System.currentTimeMillis();
166	    } finally {
167	      synchronized (refreshLock) {
168	        refreshing = false;
169	      }
170	    }
171	  }
172	
173	  private @Nullable File resolveWorkDir() {
174	    if (project.isDisposed()) return null;
175	    VirtualFile[] roots = ProjectRootManager.getInstance(project).getContentRoots();
176	    for (VirtualFile root : roots) {
177	      File f = toLocalDir(root);
178	      if (f != null) return f;
179	    }
180	    String basePath = project.getBasePath();
181	    if (basePath == null) return null;
182	    VirtualFile baseDir = LocalFileSystem.getInstance().findFileByPath(basePath);
183	    File f = toLocalDir(baseDir);
184	    return f != null ? f : new File(basePath);
185	  }
