190	   * schedule a background refresh.
191	   */
192	  public void setCachedContributorsForTesting(@NotNull List<String> contributors) {
193	    this.cached = List.copyOf(contributors);
194	    this.lastRefreshMs = System.currentTimeMillis();
195	  }
