package net.wolfig.codeowls.matcher;

import org.junit.Test;

import java.util.List;

import static org.junit.Assert.*;

/**
 * Tests for {@link CodeownersSection} — a pure data record with a single piece
 * of behaviour, {@link CodeownersSection#displayHeader()}, which reconstructs
 * the GitLab section header roughly as it appears in the file.
 *
 * <p>Tests follow the Arrange / Act / Assert pattern.
 */
public class CodeownersSectionTest {

  @Test
  public void displayHeader_optionalWithApprovalAndOwners_rendersAllParts() {
    // Arrange
    CodeownersSection section = new CodeownersSection(
            "Backend", true, List.of("@org/backend", "@alice"), 2);

    // Act
    String header = section.displayHeader();

    // Assert
    assertEquals("^[Backend][2] @org/backend @alice", header);
  }

  @Test
  public void displayHeader_mandatorySectionNoApprovalSingleOwner_rendersNameAndOwner() {
    // Arrange
    CodeownersSection section = new CodeownersSection(
            "Documentation", false, List.of("@docs-team"), null);

    // Act
    String header = section.displayHeader();

    // Assert
    assertEquals("[Documentation] @docs-team", header);
  }

  @Test
  public void displayHeader_noOwnersNoApproval_rendersJustTheName() {
    // Arrange
    CodeownersSection section = new CodeownersSection("Misc", false, List.of(), null);

    // Act
    String header = section.displayHeader();

    // Assert
    assertEquals("[Misc]", header);
  }

  @Test
  public void displayHeader_approvalCountButNoOwners_rendersNameAndCount() {
    // Arrange
    CodeownersSection section = new CodeownersSection("Backend", false, List.of(), 3);

    // Act
    String header = section.displayHeader();

    // Assert
    assertEquals("[Backend][3]", header);
  }

  @Test
  public void accessors_returnConstructorValues() {
    // Arrange
    CodeownersSection section = new CodeownersSection(
            "Backend", true, List.of("@a", "@b"), 1);

    // Assert
    assertEquals("Backend", section.name());
    assertTrue(section.optional());
    assertEquals(List.of("@a", "@b"), section.defaultOwners());
    assertEquals(Integer.valueOf(1), section.approvalCount());
  }
}

package net.wolfig.codeowls.explain;

import net.wolfig.codeowls.matcher.CodeownersGlob;
import net.wolfig.codeowls.matcher.CodeownersRule;
import net.wolfig.codeowls.matcher.CodeownersSection;
import org.junit.Test;

import java.util.List;

import static org.junit.Assert.*;

/**
 * Tests for {@link MatchedRule} — a thin wrapper over {@link CodeownersRule}
 * that adds the {@code effective} flag and delegates every other accessor to
 * the wrapped rule. These tests pin that delegation so the wrapper cannot
 * silently diverge from the rule model.
 *
 * <p>Pure JUnit — no IntelliJ platform needed ({@link CodeownersRule} accepts a
 * {@code null} source file).
 *
 * <p>Tests follow the Arrange / Act / Assert pattern.
 */
public class MatchedRuleTest {

  private static CodeownersRule ruleInSection(String pattern, List<String> owners,
                                              Integer approvalCount, CodeownersSection section,
                                              boolean ownersInherited) {
    return new CodeownersRule(pattern, owners, CodeownersGlob.compile(pattern),
            null, 7, approvalCount, section, ownersInherited);
  }

  @Test
  public void accessors_delegateToWrappedRule() {
    // Arrange
    CodeownersSection section = new CodeownersSection("Backend", false, List.of("@backend-team"), 2);
    CodeownersRule rule = ruleInSection("/src/**", List.of("@backend-team"), 2, section, true);

    // Act
    MatchedRule matched = new MatchedRule(rule, true);

    // Assert
    assertSame(rule, matched.rule());
    assertEquals("/src/**", matched.pattern());
    assertEquals(List.of("@backend-team"), matched.resolvedOwners());
    assertEquals(Integer.valueOf(2), matched.approvalCount());
    assertNull(matched.sourceFile());
    assertEquals(7, matched.line());
    assertSame(section, matched.section());
    assertTrue(matched.inheritedFromSection());
  }

  @Test
  public void effective_reflectsConstructorFlag() {
    // Arrange
    CodeownersRule rule = ruleInSection("*.java", List.of("@backend"), null, null, false);

    // Assert
    assertTrue(new MatchedRule(rule, true).effective());
    assertFalse(new MatchedRule(rule, false).effective());
  }

  @Test
  public void ruleOutsideSection_hasNullSectionAndNotInherited() {
    // Arrange — a plain rule with no enclosing section.
    CodeownersRule rule = new CodeownersRule("*.java", List.of("@backend"),
            CodeownersGlob.compile("*.java"), null, 0);

    // Act
    MatchedRule matched = new MatchedRule(rule, true);

    // Assert
    assertNull(matched.section());
    assertFalse(matched.inheritedFromSection());
    assertNull(matched.approvalCount());
  }
}

package net.wolfig.codeowls.explain;

import com.intellij.openapi.vfs.VirtualFile;
import com.intellij.testFramework.LightVirtualFile;
import net.wolfig.codeowls.matcher.CodeownersGlob;
import net.wolfig.codeowls.matcher.CodeownersRule;
import org.junit.Test;

import java.util.List;

import static org.junit.Assert.*;

/**
 * Tests for {@link OwnershipExplanation} — the immutable evaluation trace behind
 * the "Explain CODEOWNERS Ownership" action. Focuses on its pure derivation
 * logic: which rule is effective (last-match-wins), the effective owners /
 * approval count, and the empty / no-CODEOWNERS states.
 *
 * <p>Uses {@link LightVirtualFile} for the required file references — none of
 * the exercised methods touch VFS internals, so no fixture is needed.
 *
 * <p>Tests follow the Arrange / Act / Assert pattern.
 */
public class OwnershipExplanationTest {

  private static final VirtualFile TARGET = new LightVirtualFile("PaymentService.java");
  private static final VirtualFile CODEOWNERS = new LightVirtualFile("CODEOWNERS");

  private static CodeownersRule rule(String pattern, Integer approvalCount, String... owners) {
    return new CodeownersRule(pattern, List.of(owners), CodeownersGlob.compile(pattern),
            null, 0, approvalCount);
  }

  @Test
  public void of_multipleMatches_marksOnlyTheLastEffectiveAndPreservesOrder() {
    // Arrange
    CodeownersRule first = rule("/src/**", null, "@developers");
    CodeownersRule second = rule("/src/payment/**", null, "@backend");
    CodeownersRule third = rule("/src/payment/*.java", null, "@payment-team");

    // Act
    OwnershipExplanation explanation = OwnershipExplanation.of(
            TARGET, "src/payment/PaymentService.java", CODEOWNERS, List.of(first, second, third));

    // Assert
    List<MatchedRule> matched = explanation.matchedRules();
    assertEquals(3, matched.size());
    assertSame(first, matched.get(0).rule());
    assertSame(second, matched.get(1).rule());
    assertSame(third, matched.get(2).rule());
    assertFalse(matched.get(0).effective());
    assertFalse(matched.get(1).effective());
    assertTrue(matched.get(2).effective());
    assertSame(matched.get(2), explanation.effectiveRule());
  }

  @Test
  public void of_singleMatch_isEffectiveAndDrivesOwnersAndApprovals() {
    // Arrange
    CodeownersRule only = rule("*.java", 2, "@backend", "@alice");

    // Act
    OwnershipExplanation explanation = OwnershipExplanation.of(
            TARGET, "Foo.java", CODEOWNERS, List.of(only));

    // Assert
    assertTrue(explanation.hasMatch());
    assertTrue(explanation.hasCodeownersFile());
    assertTrue(explanation.matchedRules().getFirst().effective());
    assertEquals(List.of("@backend", "@alice"), explanation.effectiveOwners());
    assertEquals(Integer.valueOf(2), explanation.effectiveApprovalCount());
  }

  @Test
  public void of_noMatches_hasCodeownersButNoEffectiveRule() {
    // Arrange — a governing CODEOWNERS file exists, but nothing matched.
    OwnershipExplanation explanation = OwnershipExplanation.of(
            TARGET, "Foo.java", CODEOWNERS, List.of());

    // Assert
    assertTrue(explanation.hasCodeownersFile());
    assertFalse(explanation.hasMatch());
    assertNull(explanation.effectiveRule());
    assertTrue(explanation.effectiveOwners().isEmpty());
    assertNull(explanation.effectiveApprovalCount());
  }

  @Test
  public void noCodeowners_reportsNoFileAndNoMatch() {
    // Act
    OwnershipExplanation explanation = OwnershipExplanation.noCodeowners(TARGET);

    // Assert
    assertSame(TARGET, explanation.targetFile());
    assertNull(explanation.relativePath());
    assertNull(explanation.codeownersFile());
    assertFalse(explanation.hasCodeownersFile());
    assertFalse(explanation.hasMatch());
    assertNull(explanation.effectiveRule());
    assertTrue(explanation.effectiveOwners().isEmpty());
  }

  @Test
  public void of_matchedRules_isImmutable() {
    // Arrange
    OwnershipExplanation explanation = OwnershipExplanation.of(
            TARGET, "Foo.java", CODEOWNERS, List.of(rule("*.java", null, "@backend")));

    // Act / Assert — the exposed list must not be modifiable.
    assertThrows(UnsupportedOperationException.class,
            () -> explanation.matchedRules().clear());
  }
}

package net.wolfig.codeowls.suggestion;

import org.junit.Test;

import static org.junit.Assert.*;

/**
 * Tests for {@link OwnerSuggestion} — a data record whose only behaviour is
 * {@link OwnerSuggestion#confidencePercent()}, which rounds the {@code [0, 1]}
 * confidence to a whole percentage.
 *
 * <p>Tests follow the Arrange / Act / Assert pattern.
 */
public class OwnerSuggestionTest {

  private static OwnerSuggestion withConfidence(double confidence) {
    return new OwnerSuggestion("@api-team", "already used in CODEOWNERS", confidence);
  }

  @Test
  public void confidencePercent_zero_isZero() {
    assertEquals(0, withConfidence(0.0).confidencePercent());
  }

  @Test
  public void confidencePercent_one_isHundred() {
    assertEquals(100, withConfidence(1.0).confidencePercent());
  }

  @Test
  public void confidencePercent_half_isFifty() {
    assertEquals(50, withConfidence(0.5).confidencePercent());
  }

  @Test
  public void confidencePercent_roundsToNearestWholePercent() {
    // Arrange / Act / Assert — 78.6% rounds up, 78.4% rounds down.
    assertEquals(79, withConfidence(0.786).confidencePercent());
    assertEquals(78, withConfidence(0.784).confidencePercent());
  }

  @Test
  public void accessors_returnConstructorValues() {
    // Arrange
    OwnerSuggestion suggestion = new OwnerSuggestion("@alice", "git history", 0.42);

    // Assert
    assertEquals("@alice", suggestion.owner());
    assertEquals("git history", suggestion.source());
    assertEquals(0.42, suggestion.confidence(), 1e-9);
  }
}

package net.wolfig.codeowls.action;

import com.intellij.openapi.actionSystem.ActionUpdateThread;
import com.intellij.openapi.actionSystem.DefaultActionGroup;
import org.junit.Test;

import static org.junit.Assert.*;

/**
 * Tests for {@link CodeowlsActionGroup}, the "Codeowls" context-menu submenu.
 *
 * <p>Tests follow the Arrange / Act / Assert pattern.
 */
public class CodeowlsActionGroupTest {

  @Test
  public void isDefaultActionGroup() {
    assertTrue(new CodeowlsActionGroup() instanceof DefaultActionGroup);
  }

  @Test
  public void getActionUpdateThread_isBackground() {
    // The group computes child visibility off the EDT, matching its actions.
    assertEquals(ActionUpdateThread.BGT, new CodeowlsActionGroup().getActionUpdateThread());
  }
}

