3	import com.intellij.openapi.vfs.VirtualFile;
4	import com.intellij.psi.PsiFile;
5	import com.intellij.psi.util.CachedValueProvider;
6	import com.intellij.psi.util.CachedValuesManager;
7	import com.intellij.psi.util.PsiModificationTracker;
8	import net.wolfig.codeowls.matcher.CodeownersRule;
9	import net.wolfig.codeowls.matcher.CodeownersRuleParser;
10	import org.jetbrains.annotations.NotNull;
11	import org.jetbrains.annotations.Nullable;
12	
13	import java.util.*;
14	
15	/**
16	 * Counts how many project files each CODEOWNERS rule matches.
17	 *
18	 * <p>The result is cached per CODEOWNERS {@link PsiFile} via
19	 * {@link CachedValuesManager} and invalidated on PSI changes. The inlay-hint
20	 * collector calls into this class on every pass; without the cache it would
21	 * re-walk the project tree and re-run every rule on every repaint.
22	 *
23	 * <p>Single-file (exact-path) rules and obviously irrelevant lines (comments,
24	 * empty lines, malformed lines, section headers — anything {@link
25	 * CodeownersRuleParser} doesn't surface as a rule) are skipped: a "1 file"
26	 * hint on a rule that already names a specific path adds nothing.
27	 *
28	 * <p>For tests and reuse the heavy lifting lives in
29	 * {@link #computeCountsByLine(CharSequence, VirtualFile, List)} — a pure
30	 * function that takes the CODEOWNERS text and a precomputed list of project
31	 * file paths.
32	 */
33	public final class CodeownersMatchCounter {
34	
35	  /**
36	   * Directory names skipped when walking project files. Matches the path completion list.
37	   */
38	  static final Set<String> IGNORED_DIRECTORY_NAMES = Set.of(
39	          ".git", ".idea", ".gradle", "node_modules", "build", "dist", "target", "out");
40	
41	  private CodeownersMatchCounter() {
42	  }
43	
44	  /**
45	   * @return a (line → match-count) map for {@code codeownersFile}, cached on
46	   * the PSI file and invalidated on any PSI modification. Lines that aren't
47	   * glob-style rules (comments, headers, malformed lines, exact-path rules)
48	   * are absent from the map rather than reported as zero.
49	   */
50	  public static @NotNull Map<Integer, Integer> countsByLine(@NotNull PsiFile codeownersFile) {
51	    return CachedValuesManager.getCachedValue(codeownersFile, () -> {
52	      Map<Integer, Integer> counts = compute(codeownersFile);
53	      return CachedValueProvider.Result.create(counts,
54	              codeownersFile, PsiModificationTracker.MODIFICATION_COUNT);
55	    });
56	  }
57	
58	  private static @NotNull Map<Integer, Integer> compute(@NotNull PsiFile codeownersFile) {
59	    VirtualFile vf = codeownersFile.getVirtualFile();
60	    VirtualFile root = projectRoot(vf);
61	    if (root == null) return Map.of();
62	    List<String> paths = collectProjectFilePaths(root);
63	    return computeCountsByLine(codeownersFile.getViewProvider().getContents(), vf, paths);
64	  }
65	
66	  /**
67	   * Pure-logic core, exposed for tests. Parses {@code codeownersText} and,
68	   * for each glob-style rule, counts how many of {@code projectFilePaths}
69	   * (forward-slash, no leading {@code /}) the rule matches.
70	   */
71	  static @NotNull Map<Integer, Integer> computeCountsByLine(@NotNull CharSequence codeownersText,
72	                                                            @Nullable VirtualFile sourceForRules,
73	                                                            @NotNull List<String> projectFilePaths) {
74	    if (codeownersText.isEmpty()) return Map.of();
75	    List<CodeownersRule> rules = CodeownersRuleParser.parse(codeownersText, sourceForRules);
76	    Map<Integer, Integer> result = new HashMap<>();
77	    for (CodeownersRule rule : rules) {
78	      // Only emit hints for patterns whose match count is non-trivial: a glob
79	      // (contains *, ?, [, ]) or a directory pattern (ends with /). Anchored
80	      // file paths and bare basenames almost always resolve to a single file,
81	      // so the "// 1 file" hint just adds visual noise.
82	      if (!isGlobOrDirectoryPattern(rule.pattern())) continue;
83	      int matches = 0;
84	      for (String path : projectFilePaths) {
85	        if (rule.matches(path)) matches++;
86	      }
87	      result.put(rule.lineNumber(), matches);
88	    }
89	    return result;
90	  }
91	
92	  /**
93	   * The directory CODEOWNERS patterns are written against. Mirrors the
94	   * heuristic used by {@code CodeownersPathCompletionProvider}: a CODEOWNERS
95	   * file under {@code .github/}, {@code .gitlab/}, or {@code docs/} resolves
96	   * to its grandparent; otherwise its parent.
97	   */
98	  public static @Nullable VirtualFile projectRoot(@Nullable VirtualFile codeownersFile) {
99	    if (codeownersFile == null) return null;
100	    VirtualFile parent = codeownersFile.getParent();
101	    if (parent == null) return null;
102	    String name = parent.getName();
103	    if (name.equals(".github") || name.equals(".gitlab") || name.equals("docs")) {
104	      VirtualFile gp = parent.getParent();
105	      return gp != null ? gp : parent;
106	    }
107	    return parent;
108	  }
109	
110	  /**
111	   * Collect every regular file under {@code root}, returned as project-relative
112	   * forward-slash paths (no leading {@code /}). Ignored build/VCS folders are
113	   * skipped before recursion. Package-private for tests.
114	   */
115	  public static @NotNull List<String> collectProjectFilePaths(@NotNull VirtualFile root) {
116	    List<String> result = new ArrayList<>();
117	    walk(root, "", result);
118	    return result;
119	  }
120	
121	  /**
122	   * @return {@code true} if {@code pattern} is either a directory pattern
123	   * (ends with {@code /}) or contains any glob metacharacter
124	   * ({@code *}, {@code ?}, {@code [}, {@code ]}). Patterns that satisfy
125	   * neither condition (anchored file paths and bare basenames) are excluded
126	   * from the inlay hint — they're either guaranteed to match a single file
127	   * or, in practice, almost always do.
128	   */
129	  public static boolean isGlobOrDirectoryPattern(@NotNull String pattern) {
130	    if (pattern.isEmpty()) return false;
131	    if (pattern.endsWith("/")) return true;
132	    for (int i = 0; i < pattern.length(); i++) {
133	      char c = pattern.charAt(i);
134	      if (c == '*' || c == '?' || c == '[' || c == ']') return true;
135	    }
136	    return false;
137	  }
138	
139	  private static void walk(@NotNull VirtualFile dir, @NotNull String prefix, @NotNull List<String> out) {
140	    for (VirtualFile child : dir.getChildren()) {
141	      if (!child.isValid()) continue;
142	      String name = child.getName();
143	      String next = prefix.isEmpty() ? name : prefix + "/" + name;
144	      if (child.isDirectory()) {
145	        if (IGNORED_DIRECTORY_NAMES.contains(name)) continue;
146	        walk(child, next, out);
147	      } else {
148	        out.add(next);
149	      }
150	    }
151	  }
152	}
