package net.wolfig.codeowls.inspection;

import com.intellij.codeInsight.daemon.impl.HighlightInfo;
import com.intellij.codeInsight.intention.IntentionAction;
import com.intellij.testFramework.fixtures.CodeInsightTestFixture;
import com.intellij.testFramework.fixtures.IdeaProjectTestFixture;
import com.intellij.testFramework.fixtures.IdeaTestFixtureFactory;
import com.intellij.testFramework.fixtures.TestFixtureBuilder;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import java.util.List;

import static org.junit.Assert.*;

/**
 * Tests for {@link CodeownersUnnecessaryRuleInspection} — the LocalInspectionTool
 * that turns {@link CodeownersRedundancyAnalyzer} findings into editor warnings
 * with a "remove rule" quick fix.
 *
 * <p>The analyzer's decision logic is covered by
 * {@code CodeownersRedundancyAnalyzerTest}; these fixture tests cover the
 * wiring the wrapper adds: findings become highlights with the right message,
 * and the quick fix deletes the offending rule line. A real project tree is
 * needed so the inspection can tell which patterns match a file.
 *
 * <p>Tests follow the Arrange / Act / Assert pattern.
 */
public class CodeownersUnnecessaryRuleInspectionTest {

  private CodeInsightTestFixture fixture;

  @Before
  public void setUp() throws Exception {
    IdeaTestFixtureFactory factory = IdeaTestFixtureFactory.getFixtureFactory();
    TestFixtureBuilder<IdeaProjectTestFixture> builder =
            factory.createLightFixtureBuilder(getClass().getName());
    fixture = factory.createCodeInsightFixture(builder.getFixture());
    fixture.setUp();
    fixture.enableInspections(new CodeownersUnnecessaryRuleInspection());
  }

  @After
  public void tearDown() throws Exception {
    if (fixture != null) {
      fixture.tearDown();
      fixture = null;
    }
  }

  @Test
  public void inspection_patternMatchingNoProjectFile_isFlagged() {
    // Arrange — the project has a .java file but no .kt file.
    fixture.addFileToProject("src/Foo.java", "");
    var codeowners = fixture.addFileToProject("CODEOWNERS", "*.kt @kotlin\n");
    fixture.configureFromExistingVirtualFile(codeowners.getVirtualFile());

    // Act
    List<HighlightInfo> infos = fixture.doHighlighting();

    // Assert
    assertTrue("expected a 'matches no files' warning, got: " + descriptions(infos),
            infos.stream().anyMatch(i -> hasDescription(i, "matches no files")));
  }

  @Test
  public void inspection_ruleShadowedByLaterIdenticalRule_isFlagged() {
    // Arrange — the first rule is fully shadowed by the identical later one; a
    // matching file exists so neither is a "no files match" case.
    fixture.addFileToProject("src/Foo.java", "");
    var codeowners = fixture.addFileToProject("CODEOWNERS", "*.java @first\n*.java @second\n");
    fixture.configureFromExistingVirtualFile(codeowners.getVirtualFile());

    // Act
    List<HighlightInfo> infos = fixture.doHighlighting();

    // Assert
    assertTrue("expected a 'shadowed by' warning, got: " + descriptions(infos),
            infos.stream().anyMatch(i -> hasDescription(i, "is shadowed by the rule on line")));
  }

  @Test
  public void inspection_allRulesUseful_producesNoFindings() {
    // Arrange — every rule matches a real file and none shadows another.
    fixture.addFileToProject("src/Foo.java", "");
    fixture.addFileToProject("docs/Guide.md", "");
    var codeowners = fixture.addFileToProject("CODEOWNERS", "*.java @backend\n*.md @docs\n");
    fixture.configureFromExistingVirtualFile(codeowners.getVirtualFile());

    // Act
    List<HighlightInfo> infos = fixture.doHighlighting();

    // Assert
    assertFalse("no CODEOWNERS warnings expected, got: " + descriptions(infos),
            infos.stream().anyMatch(i -> hasDescription(i, "matches no files")
                    || hasDescription(i, "is shadowed by the rule on line")));
  }

  @Test
  public void quickFix_removesTheFlaggedRuleLine() {
    // Arrange — the flagged rule is first, so the default caret (offset 0) sits
    // on it and its "remove rule" fix is the single available intention.
    fixture.addFileToProject("src/Foo.java", "");
    var codeowners = fixture.addFileToProject("CODEOWNERS", "*.kt @kotlin\n*.java @backend\n");
    fixture.configureFromExistingVirtualFile(codeowners.getVirtualFile());
    fixture.doHighlighting();

    // Act
    IntentionAction fix = fixture.findSingleIntention("Remove CODEOWNERS rule");
    fixture.launchAction(fix);

    // Assert — only the unnecessary *.kt line is gone.
    fixture.checkResult("*.java @backend\n");
  }

  private static boolean hasDescription(HighlightInfo info, String needle) {
    return info.getDescription() != null && info.getDescription().contains(needle);
  }

  private static List<String> descriptions(List<HighlightInfo> infos) {
    return infos.stream().map(HighlightInfo::getDescription).toList();
  }
}

package net.wolfig.codeowls.navigation;

import com.intellij.psi.PsiFile;
import com.intellij.testFramework.fixtures.CodeInsightTestFixture;
import com.intellij.testFramework.fixtures.IdeaProjectTestFixture;
import com.intellij.testFramework.fixtures.IdeaTestFixtureFactory;
import com.intellij.testFramework.fixtures.TestFixtureBuilder;
import net.wolfig.codeowls.lang.CodeownersFileType;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.*;

/**
 * Tests for {@link OpenUrlInBrowserElement} — the fake PSI element that
 * {@code CodeownersOwnerGotoDeclarationHandler} returns so Ctrl/Cmd+Click on an
 * owner opens a URL instead of moving the caret.
 *
 * <p>These pin the properties that make GotoDeclaration take the browser path:
 * a {@code null} containing file and {@code canNavigate}/{@code canNavigateToSource}
 * flags. {@link OpenUrlInBrowserElement#navigate} itself is not exercised — it
 * would launch a real browser. Same-package so the package-private class is
 * visible.
 *
 * <p>Tests follow the Arrange / Act / Assert pattern.
 */
public class OpenUrlInBrowserElementTest {

  private static final String URL = "https://github.com/orgs/acme/teams/backend";

  private CodeInsightTestFixture fixture;
  private PsiFile parent;

  @Before
  public void setUp() throws Exception {
    IdeaTestFixtureFactory factory = IdeaTestFixtureFactory.getFixtureFactory();
    TestFixtureBuilder<IdeaProjectTestFixture> builder =
            factory.createLightFixtureBuilder(getClass().getName());
    fixture = factory.createCodeInsightFixture(builder.getFixture());
    fixture.setUp();
    parent = fixture.configureByText(CodeownersFileType.INSTANCE, "*.java @org/backend\n");
  }

  @After
  public void tearDown() throws Exception {
    if (fixture != null) {
      fixture.tearDown();
      fixture = null;
    }
  }

  @Test
  public void getName_returnsTheUrl() {
    assertEquals(URL, new OpenUrlInBrowserElement(parent, URL).getName());
  }

  @Test
  public void getContainingFile_isNull_soGotoTakesTheNavigatablePath() {
    // A non-null file equal to the editor's would make GotoDeclaration move the
    // caret in-editor instead of opening the browser.
    assertNull(new OpenUrlInBrowserElement(parent, URL).getContainingFile());
  }

  @Test
  public void navigationFlags_navigableButNotToSource() {
    OpenUrlInBrowserElement element = new OpenUrlInBrowserElement(parent, URL);
    assertTrue(element.canNavigate());
    assertFalse(element.canNavigateToSource());
  }

  @Test
  public void getParentAndProject_delegateToTheParentElement() {
    OpenUrlInBrowserElement element = new OpenUrlInBrowserElement(parent, URL);
    assertSame(parent, element.getParent());
    assertSame(parent.getProject(), element.getProject());
  }
}

