10	/**
11	 * Finds CODEOWNERS rules that carry no weight, given the project's files.
12	 *
13	 * <p>Resolution is last-match-wins, so a single pass over the project files is
14	 * enough to classify every rule:
15	 * <ul>
16	 *   <li>{@link Kind#NO_FILES_MATCH} — the rule matches no project file at all
17	 *       (the path/glob points at something that does not exist).</li>
18	 *   <li>{@link Kind#SHADOWED} — the rule matches files, but a <em>later</em>
19	 *       rule wins for every one of them, so it never decides ownership. The
20	 *       index of an overriding rule is reported for the diagnostic message.</li>
21	 * </ul>
22	 *
23	 * <p>A rule that wins for at least one file is never flagged, even if other
24	 * rules also cover some of its files. Negation patterns ({@code !…}) are not
25	 * analysed: {@link net.wolfig.codeowls.matcher.CodeownersGlob} strips the
26	 * {@code !}, so treating them as positive matches here would mislead.
27	 *
28	 * <p>Pure and deterministic — unit-tested without the IntelliJ platform.
29	 */
30	public final class CodeownersRedundancyAnalyzer {
31	
32	  private CodeownersRedundancyAnalyzer() {
33	  }
34	
35	  public static @NotNull List<Finding> analyze(@NotNull List<CodeownersRule> rules,
36	                                               @NotNull List<String> projectFilePaths) {
37	    int n = rules.size();
38	    if (n == 0) return List.of();
39	
40	    boolean[] analyzable = new boolean[n];
41	    for (int i = 0; i < n; i++) analyzable[i] = isAnalyzable(rules.get(i).pattern());
42	
43	    boolean[] matchedAny = new boolean[n];
44	    boolean[] everWinner = new boolean[n];
45	    int[] shadowedBy = new int[n];
46	    Arrays.fill(shadowedBy, -1);
47	
48	    List<Integer> matched = new ArrayList<>();
49	    for (String path : projectFilePaths) {
50	      matched.clear();
51	      for (int i = 0; i < n; i++) {
52	        if (analyzable[i] && rules.get(i).matches(path)) {
53	          matched.add(i);
54	          matchedAny[i] = true;
55	        }
56	      }
57	      if (matched.isEmpty()) continue;
58	      int winner = matched.get(matched.size() - 1);
59	      everWinner[winner] = true;
60	      // Every earlier matching rule is overridden by `winner` for this file.
61	      for (int k = 0; k < matched.size() - 1; k++) {
62	        int shadowed = matched.get(k);
63	        if (shadowedBy[shadowed] < 0) shadowedBy[shadowed] = winner;
64	      }
65	    }
66	
67	    List<Finding> findings = new ArrayList<>();
68	    for (int i = 0; i < n; i++) {
69	      if (!analyzable[i]) continue;
70	      if (!matchedAny[i]) {
71	        findings.add(new Finding(i, Kind.NO_FILES_MATCH, -1));
72	      } else if (!everWinner[i]) {
73	        findings.add(new Finding(i, Kind.SHADOWED, shadowedBy[i]));
74	      }
75	    }
76	    return findings;
77	  }
78	
79	  static boolean isAnalyzable(@NotNull String pattern) {
80	    return !pattern.isBlank() && !pattern.startsWith("!");
81	  }
82	
83	  public enum Kind {NO_FILES_MATCH, SHADOWED}
84	
85	  /**
86	   * @param ruleIndex          index of the unnecessary rule
87	   * @param kind               why it is unnecessary
88	   * @param shadowingRuleIndex for {@link Kind#SHADOWED}, the index of a rule that
89	   *                           overrides it; {@code -1} otherwise
90	   */
91	  public record Finding(int ruleIndex, @NotNull Kind kind, int shadowingRuleIndex) {
92	  }
93	}
